# Find all "hole" cells - background cells (1) completely surrounded by pattern (6)
def has_6_neighbor(grid, r, c):
    lines = len(grid)
    cols = len(grid[0])
    # Check 4 cardinal neighbors
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < lines and 0 <= nc < cols:
            if grid[nr][nc] == 6:
                return True
    return False

def is_hole(grid, r, c):
    # Background cell surrounded by pattern cells
    return grid[r][c] == 1 and has_6_neighbor(grid, r, c)

holes = []
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if is_hole(grid, r, c):
            holes.append((r, c))

print(f"Hole cells: {holes}")

# Check each hole individually
for r, c in holes:
    print(f"\nHole ({r},{c}) neighbors:")
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            print(f"  ({nr},{nc}) = {grid[nr][nc]}", end=" ")
        else:
            print(f"  ({nr},{nc}) = edge", end=" ")
    print()

